    #region Collection will display as a ComboBox in PropertyGrid on the fly.    public class FileListProperty {        public static List<string> FilesList = new List<string>() {            "radius_20_offset_3_thickness_6.png",            "radius_20_offset_5_thickness_8.png"        };    }    public class FileListPropertyConverter : StringConverter {        public override bool GetStandardValuesSupported(ITypeDescriptorContext context) {            //true means show a combobox            return true;        }        public override bool GetStandardValuesExclusive(ITypeDescriptorContext context) {            //true will limit to list. false will show the list,             //but allow free-form entry            return true;        }        public override System.ComponentModel.TypeConverter.StandardValuesCollection               GetStandardValues(ITypeDescriptorContext context) {            return new StandardValuesCollection(FileListProperty.FilesList);        }    }    #endregion         [CategoryAttribute("VZHLED"),            DisplayName("Typ schránky"),            DescriptionAttribute("Typ schránky"),            TypeConverter(typeof(FileListPropertyConverter))        ]        string CageStyle { get; set; }        public string CageStyle {            //When first loaded set property with the first item in the rule list.            get {                string S = "";                if (_cageStyle != null) {                    S = _cageStyle;                } else {                    if (FileListProperty.FilesList.Count > 0) {                        //Sort the list before displaying it                        Array.Sort(FileListProperty.FilesList.ToArray());                        S = FileListProperty.FilesList[0];                    }                }                return S;            }            set {                _cageStyle = value;            }        }